   868	                                boost::bind(&NCPInstanceBase::check_ncp_entry_update_status, this, _1, "adding on-mesh prefix", cb));
   869	                } else {
   870	                        cb(kWPANTUNDStatus_Ok);
   871	                }
   872	        } else {
   873	                cb(kWPANTUNDStatus_Ok);
   874	        }
